use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap = 1
    let mut first = true
    let mut keys: Vec<int> = []
    let mut vals: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut nk: Vec<int> = [k]
            let mut nv: Vec<int> = [v]
            let mut i = 0
            while i < keys.len() {
                if keys[i] != k {
                    nk.push(keys[i])
                    nv.push(vals[i])
                }
                i += 1
            }
            if nk.len() as int > cap {
                println("evict ${nk[nk.len() - 1]}")
                nk.pop()
                nv.pop()
            }
            keys = nk
            vals = nv
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found = -1
            let mut idx = -1
            let mut i = 0
            while i < keys.len() {
                if keys[i] == k {
                    idx = i as int
                    found = vals[i]
                }
                i += 1
            }
            println("${found}")
            if idx >= 0 {
                let mut nk: Vec<int> = [k]
                let mut nv: Vec<int> = [found]
                let mut j = 0
                while j < keys.len() {
                    if keys[j] != k {
                        nk.push(keys[j])
                        nv.push(vals[j])
                    }
                    j += 1
                }
                keys = nk
                vals = nv
            }
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut s = ""
                let mut i = 0
                while i < keys.len() {
                    if i > 0 {
                        s = s + " "
                    }
                    s = s + "${keys[i]}"
                    i += 1
                }
                println("${s}")
            }
        }
    }
}

